  if(item.primarySource){viewer.records.set(item.primarySource.id,item.primarySource);return;}const word=currentWord(),entries=item.entries.filter(e=>e.word===word),id='page_'+index,old=window.SCHOOL_CURRENT_PAGE_SOURCE.records[id];if(!entries.length)return;
